// Characterization tests: pin the current client-visible behaviour of the HTTP API,
// including quirks (marked "quirk"), so a restructuring can't change them unnoticed.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { apple: 10, pear: 2.5, gold: 60, cheap: 0.3 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})
const call = async (res) => ({ status: res.status, type: res.headers.get('content-type'), body: await res.json() })

test('POST /orders creates an order: 201, json, id, items, total', async () => {
  const r = await call(await post({ items: [{ sku: 'apple', qty: 2 }] }))
  assert.equal(r.status, 201)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(Object.keys(r.body).sort(), ['id', 'items', 'total'])
  assert.equal(typeof r.body.id, 'string')
  assert.deepEqual(r.body.items, [{ sku: 'apple', qty: 2 }])
  assert.equal(r.body.total, 20)
})

test('ids are strings and increment by one', async () => {
  const a = (await call(await post({ items: [{ sku: 'apple', qty: 1 }] }))).body.id
  const b = (await call(await post({ items: [{ sku: 'apple', qty: 1 }] }))).body.id
  assert.equal(Number(b), Number(a) + 1)
})

test('total sums multiple items', async () => {
  const r = await call(await post({ items: [{ sku: 'apple', qty: 1 }, { sku: 'pear', qty: 4 }] }))
  assert.equal(r.body.total, 20)
})

test('total is floored to whole units', async () => {
  const r = await call(await post({ items: [{ sku: 'pear', qty: 3 }] })) // 7.5
  assert.equal(r.body.total, 7)
})

test('no discount at exactly 100', async () => {
  const r = await call(await post({ items: [{ sku: 'apple', qty: 10 }] }))
  assert.equal(r.body.total, 100)
})

test('10% discount when total is over 100', async () => {
  const r = await call(await post({ items: [{ sku: 'apple', qty: 11 }] })) // 110 -> 99
  assert.equal(r.body.total, 99)
})

test('discount applied before flooring', async () => {
  const r = await call(await post({ items: [{ sku: 'gold', qty: 2 }, { sku: 'pear', qty: 1 }] })) // 122.5 -> 110.25
  assert.equal(r.body.total, 110)
})

test('GET /orders/:id returns the created order', async () => {
  const created = (await call(await post({ items: [{ sku: 'apple', qty: 3 }] }))).body
  const r = await call(await fetch(`${base}/orders/${created.id}`))
  assert.equal(r.status, 200)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(r.body, created)
})

test('quirk: GET unknown order returns 200 with {error:"not found"}', async () => {
  const r = await call(await fetch(`${base}/orders/does-not-exist`))
  assert.equal(r.status, 200)
  assert.deepEqual(r.body, { error: 'not found' })
})

for (const [name, body, raw] of [
  ['missing items', {}],
  ['items not an array', { items: 'x' }],
  ['empty items', { items: [] }],
  ['invalid JSON', null, '{nope'],
  ['null body', null, 'null'],
]) {
  test(`POST /orders 400 for ${name}`, async () => {
    const r = await call(await post(body, raw))
    assert.equal(r.status, 400)
    assert.equal(r.type, 'application/json')
    assert.deepEqual(r.body, { error: 'items required' })
  })
}

test('quirk: empty POST body is treated as {} -> 400', async () => {
  const r = await call(await fetch(`${base}/orders`, { method: 'POST' }))
  assert.equal(r.status, 400)
})

test('failed creation does not consume an id', async () => {
  const a = (await call(await post({ items: [{ sku: 'apple', qty: 1 }] }))).body.id
  await post({ items: [] })
  const b = (await call(await post({ items: [{ sku: 'apple', qty: 1 }] }))).body.id
  assert.equal(Number(b), Number(a) + 1)
})

test('unknown route -> 404 {error:"no route"}', async () => {
  for (const [method, path] of [['GET', '/nope'], ['GET', '/orders'], ['GET', '/orders/1/extra'], ['DELETE', '/orders/1'], ['PUT', '/orders'], ['POST', '/orders/1']]) {
    const r = await call(await fetch(base + path, { method }))
    assert.equal(r.status, 404, `${method} ${path}`)
    assert.deepEqual(r.body, { error: 'no route' })
  }
})

test('query string is ignored when routing', async () => {
  const created = (await call(await post({ items: [{ sku: 'apple', qty: 1 }] }))).body
  const r = await call(await fetch(`${base}/orders/${created.id}?x=1`))
  assert.deepEqual(r.body, created)
})
